head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > redrawColumn]<br/>Body Column 정보를 사용하여 특정 Body Column 을 다시 렌더링합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Body Row MultiLine 구성)
//  - gBody 에 <w2:row> 2개 -> 한 데이터 Row 가 2 Line 으로 표시
//  - 1줄 = col1(인덱스0) / col2(인덱스1), 2줄 = col3(인덱스2) / col4(인덱스3)
//  - Row 가 MultiLine 이어도 col1~col4 는 각각 고유 인덱스(0~3) 를 가짐
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // MultiLine 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body 가 MultiLine(2줄). 한 데이터 Row 가 2줄에 걸쳐 표시됨. 1줄 col1(0)/col2(1), 2줄 col3(2)/col4(3) 고유 인덱스. 데이터 Row 3개.\n[절차] 1) (GridView 값만 수정) 클릭 -> 그리드 셀의 화면(DOM) 표시값만 임시로 변경(DataList 는 원본 그대로 -> 화면과 DataList 불일치). 2) columnInfo(0~3) 선택 후 (redrawColumn 실행) -> 해당 컬럼을 DataList 값으로 다시 렌더링.\n[확인] MultiLine 이어도 col1~col4 는 고유 인덱스(0~3)로 redrawColumn 대상이 되며, 실행 시 화면 임시값이 사라지고 해당 컬럼이 DataList 원본값으로 복원되어 출력됨."', '', 'label1');

    // dataList 생성 + 초기값 바인딩 (col1~col4)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "서울 강남점", "col2": "1250", "col3": "김영업", "col4": "010-1111-2222" },
        { "col1": "부산 해운대점", "col2": "980", "col3": "이판매", "col4": "010-3333-4444" },
        { "col1": "대구 수성점", "col2": "1430", "col3": "박상담", "col4": "010-5555-6666" }
    ]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (Body Row MultiLine : gBody 에 <w2:row> 2개)
    //  - 1줄 : col1(0) / col2(1)
    //  - 2줄 : col3(2) / col4(3)
    //  - Row 가 MultiLine 이어도 모든 Column 은 고유 인덱스(0~3)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:560px;height:340px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol1" value="지점명"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="매출(만원)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol3" value="담당자"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="연락처"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="280" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    strTarget += '<w2:column width="280" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// [1단계] GridView 화면 값만 수정 : DataList 는 건드리지 않고 그리드 셀의 화면(DOM) 표시값만 임시로 변경한다.
//  -> MultiLine Row 의 모든 셀 화면값을 임시값으로. redrawColumn 이 DataList 를 다시 읽어 화면을 복원하는지 확인용.
scwin.btn_modifyAllCells_onclick = function () {
    let cnt = dlt_bind.getRowCount();
    let colCnt = target1.getColumnCount();

    // 화면에만 표시할 임시값 : 초기값과 같은 형태(지점명/매출/담당자/연락처)지만 다른 값
    let fakeMap = {
        "col1": ["인천 부평점", "대전 둔산점", "울산 남구점"],
        "col2": ["1530", "2040", "870"],
        "col3": ["최영업", "정판매", "강상담"],
        "col4": ["010-7777-8888", "010-9999-0000", "010-2222-3333"]
    };

    // 모든 표시 셀의 화면(td) 텍스트만 임시값으로 변경 (DataList 미반영)
    for (let r = 0; r < cnt; r++) {
        for (let c = 0; c < colCnt; c++) {
            let td = document.querySelector("td[id*='target1_cell_" + r + "_" + c + "']");
            if (!td) { continue; }
            let colID = target1.getColumnID(c);
            let val = (fakeMap[colID] && typeof fakeMap[colID][r] !== 'undefined') ? fakeMap[colID][r] : ("임시" + r);
            td.textContent = val;
        }
    }

    wf_body_bottom.getObj("scwin").setReturnValue("GridView 화면 값만 수정 완료 (DataList 미반영). 화면은 초기값과 비슷한 형태의 다른 값으로 바뀌었지만 DataList 는 원본 유지 -> columnInfo(0~3) 선택 후 (redrawColumn 실행) 으로 화면 복원 확인.");
}

// [2단계] redrawColumn 실행 : 선택한 컬럼(인덱스)을 DataList 값으로 다시 렌더링 -> 화면 임시값이 사라지고 DataList 원본값으로 복원된다.
//  MultiLine Row 에서도 col1~col4 는 고유 인덱스(0~3) 로 redrawColumn 대상이 된다.
scwin.btn_redrawColumn_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let colID = target1.getColumnID(columnInfo);   // MultiLine Row 에서도 col1~col4 는 고유 인덱스(0~3)
    let cnt = dlt_bind.getRowCount();

    // redrawColumn 을 인덱스로 호출 -> DataList 값을 다시 읽어 해당 컬럼 화면 복원
    target1.redrawColumn(columnInfo);

    // 복원된 해당 컬럼의 모든 Row 화면 표시값 수집
    let arr = [];
    for (let r = 0; r < cnt; r++) {
        let td = document.querySelector("td[id*='target1_cell_" + r + "_" + columnInfo + "']");
        arr.push(td ? td.textContent.trim() : '');
    }

    wf_body_bottom.getObj("scwin").setReturnValue("redrawColumn(" + columnInfo + ") [" + colID + "] -> DataList 기준으로 화면 복원 : " + arr.join(', '));
}
